/** Hand-written vocabulary and inflected forms of typical Moldovan and Romanian names (shared by tests and scripts). */
export interface Case { id: string; cls: string; terms: string[]; forms: string[] }

const P = (id: string, full: string, forms: string[]): Case => ({ id, cls: 'PERSON', terms: [full, full.split(' ').at(-1)!], forms })
const C = (id: string, terms: string[], forms: string[], cls = 'COMPANY'): Case => ({ id, cls, terms, forms })
/** A person whose first name is also declared, as needed to protect "Dragă Ștefane" or "Petre, vino". */
const PF = (id: string, full: string, forms: string[]): Case => ({ id, cls: 'PERSON', terms: [full, full.split(' ')[0]!, full.split(' ').at(-1)!], forms })

